import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"CoreLib Actions","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/codex/corelib-actions.md","filePath":"en/modules/codex/corelib-actions.md","lastUpdated":0}`),a={name:`en/modules/codex/corelib-actions.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="corelib-actions" tabindex="-1">CoreLib Actions <a class="header-anchor" href="#corelib-actions" aria-label="Permalink to “CoreLib Actions”">​</a></h1><p>When EmakiCodex is enabled, it adds advancement management stages to the CoreLib action registry. Use them in other modules&#39; rewards, triggers, or pipeline templates to grant, revoke, resync, or reset Codex nodes, to show a client-only advancement toast, or to announce an achievement server-wide.</p><div class="note custom-block"><p class="custom-block-title custom-block-title-default">NOTE</p><p>This page documents only the stages registered by EmakiCodex. CoreLib built-in stages are documented in <a href="./../corelib/actions.html">CoreLib Actions</a>.</p></div><p>All seven stages use the category <code>codex</code> and declare <code>REQUIRED_ENTITY</code>; non-player targets are skipped. The old <code>showachievementtoast</code> is now written <code>codex_show_toast</code>; the five advancement stage IDs are unchanged.</p><p>These stages act on vanilla advancements and client-side presentation. They do not change unlocked, activated, or claimed state in the category-entry codex (<code>codex/*.yml</code>).</p><p>Which player is affected comes from the source, so there is no <code>target</code> parameter any more: use <code>self</code> for the caster, or <code>player_by_name</code> for a named player.</p><h2 id="stage-overview" tabindex="-1">Stage overview <a class="header-anchor" href="#stage-overview" aria-label="Permalink to “Stage overview”">​</a></h2><table tabindex="0"><thead><tr><th>Stage ID</th><th>Description</th></tr></thead><tbody><tr><td><code>codex_grant_advancement</code></td><td>Grants one Codex node to the target player.</td></tr><tr><td><code>codex_revoke_advancement</code></td><td>Revokes one Codex node from the target player.</td></tr><tr><td><code>codex_resync_advancement</code></td><td>Resends the Codex advancement data to the target player.</td></tr><tr><td><code>codex_reset_page</code></td><td>Revokes every registered node on one page for the target player.</td></tr><tr><td><code>codex_reset_all</code></td><td>Revokes every registered Codex node for the target player.</td></tr><tr><td><code>codex_show_toast</code></td><td>Shows a client-side advancement toast without registering or granting real progress.</td></tr><tr><td><code>codex_broadcast_achievement</code></td><td>Announces an achievement to the whole server with a vanilla-style sentence.</td></tr></tbody></table><h2 id="codex-grant-advancement" tabindex="-1">codex_grant_advancement <a class="header-anchor" href="#codex-grant-advancement" aria-label="Permalink to “codex_grant_advancement”">​</a></h2><p>Grants one EmakiCodex advancement node to the target player.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>advancement</code></td><td>STRING</td><td>Yes</td><td>—</td><td>Advancement ID. Accepts <code>page/node</code> or a full NamespacedKey.</td></tr></tbody></table><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | codex_grant_advancement advancement=example/first_step&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;player_by_name name=Steve | codex_grant_advancement advancement=emakicodex:example/challenge&#39;</span></span></code></pre></div><p>A blank <code>advancement</code> fails with <code>INVALID_CONFIG</code>. An unregistered node and an already-completed node are reported together as one <code>REJECTED</code>: the advancement service&#39;s result cannot tell them apart, so narrowing the diagnostic here would be a guess.</p><p>On success the stage reports <code>advancement</code> and <code>target</code>.</p><h2 id="codex-revoke-advancement" tabindex="-1">codex_revoke_advancement <a class="header-anchor" href="#codex-revoke-advancement" aria-label="Permalink to “codex_revoke_advancement”">​</a></h2><p>Revokes one EmakiCodex advancement node from the target player.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>advancement</code></td><td>STRING</td><td>Yes</td><td>—</td><td>Advancement ID. Accepts <code>page/node</code> or a full NamespacedKey.</td></tr></tbody></table><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | codex_revoke_advancement advancement=example/first_step&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;player_by_name name=Steve | codex_revoke_advancement advancement=emakicodex:example/challenge&#39;</span></span></code></pre></div><p>A blank <code>advancement</code> fails with <code>INVALID_CONFIG</code>; an unregistered node or a node the player has not completed fails with <code>REJECTED</code>.</p><h2 id="codex-resync-advancement" tabindex="-1">codex_resync_advancement <a class="header-anchor" href="#codex-resync-advancement" aria-label="Permalink to “codex_resync_advancement”">​</a></h2><p>Resends the currently registered Codex advancement data to the target player. No parameters.</p><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | codex_resync_advancement&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;player_by_name name=Steve | codex_resync_advancement&#39;</span></span></code></pre></div><p>Useful when:</p><ul><li>A configuration reload should refresh the client advancement tree without asking players to relog.</li><li>A custom flow needs to refresh the display after granting or resetting.</li></ul><p>This stage depends on PacketEvents: a missing gateway or one that cannot resync right now fails with <code>MISSING_CONTEXT</code>, and a failed resync fails with <code>INTERNAL_ERROR</code>. On success it reports <code>target</code> and <code>player</code>.</p><h2 id="codex-reset-page" tabindex="-1">codex_reset_page <a class="header-anchor" href="#codex-reset-page" aria-label="Permalink to “codex_reset_page”">​</a></h2><p>Revokes every registered Codex node on one page for the target player.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>page</code></td><td>STRING</td><td>Yes</td><td>—</td><td>Advancement page ID, for example <code>example</code>.</td></tr></tbody></table><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | codex_reset_page page=example&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;player_by_name name=Steve | codex_reset_page page=example&#39;</span></span></code></pre></div><p>Nodes are revoked in reverse registration order, children before parents: revoking a parent first can leave the client showing progress that no longer exists.</p><p>A blank <code>page</code> fails with <code>INVALID_CONFIG</code>; a page that matches no registered node is skipped. On success the stage reports <code>target</code>, <code>player</code>, <code>mode</code>, <code>page</code>, <code>nodes</code>, and <code>revoked</code>.</p><h2 id="codex-reset-all" tabindex="-1">codex_reset_all <a class="header-anchor" href="#codex-reset-all" aria-label="Permalink to “codex_reset_all”">​</a></h2><p>Revokes every currently registered Codex node for the target player. No parameters.</p><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | codex_reset_all&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;player_by_name name=Steve | codex_reset_all&#39;</span></span></code></pre></div><p>The revoke order matches <code>codex_reset_page</code>. On success it reports <code>mode=reset_all</code>, <code>nodes</code>, and <code>revoked</code>, with <code>page</code> as an empty string.</p><h2 id="codex-show-toast" tabindex="-1">codex_show_toast <a class="header-anchor" href="#codex-show-toast" aria-label="Permalink to “codex_show_toast”">​</a></h2><p>Shows a client-side advancement toast to the target player without registering, granting, or persisting real progress. The toast is a fake advancement pushed over the wire and withdrawn again a moment later, so the removal is scheduled rather than immediate.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>title</code></td><td>STRING</td><td>Yes</td><td>—</td><td>Toast title, MiniMessage supported.</td></tr><tr><td><code>description</code></td><td>STRING</td><td>No</td><td><code>&quot;&quot;</code></td><td>Toast description, MiniMessage supported.</td></tr><tr><td><code>icon</code></td><td>STRING</td><td>No</td><td><code>minecraft-book</code></td><td>Toast icon item source. Accepts CoreLib item source shorthand and falls back to a vanilla material when it cannot be resolved.</td></tr><tr><td><code>frame</code></td><td>STRING</td><td>No</td><td><code>task</code></td><td>Toast frame: <code>task</code>, <code>goal</code>, or <code>challenge</code>.</td></tr><tr><td><code>id</code></td><td>STRING</td><td>No</td><td><code>&quot;&quot;</code></td><td>Client-side toast ID. Empty generates a random one; the final namespace is <code>emakicodex:toast/&lt;id&gt;</code>.</td></tr><tr><td><code>remove_delay</code></td><td>DURATION</td><td>No</td><td><code>20t</code></td><td>Delay before the temporary progress packet is withdrawn.</td></tr></tbody></table><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | codex_show_toast title=&quot;&lt;gold&gt;Codex Discovery&lt;/gold&gt;&quot; description=&quot;&lt;gray&gt;A new chapter is lit&lt;/gray&gt;&quot; icon=minecraft-book frame=goal id=codex_discovery remove_delay=20t&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | codex_show_toast title=&quot;&lt;yellow&gt;New recipe unlocked&lt;/yellow&gt;&quot;&#39;</span></span></code></pre></div><p>Firing the same <code>id</code> repeatedly does not let a stale removal cancel the newer toast: removals carry a one-shot token, and the tokens survive a reload, so a removal scheduled before the reload recognises that its own toast has since been replaced.</p><h2 id="codex-broadcast-achievement" tabindex="-1">codex_broadcast_achievement <a class="header-anchor" href="#codex-broadcast-achievement" aria-label="Permalink to “codex_broadcast_achievement”">​</a></h2><p>Announces an achievement to the whole server with a vanilla-style sentence. Unlike <code>codex_show_toast</code>, it only sends chat messages and pushes no client progress packet, so it does not require PacketEvents.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>title</code></td><td>STRING</td><td>Yes</td><td>—</td><td>Achievement title, MiniMessage supported.</td></tr><tr><td><code>description</code></td><td>STRING</td><td>No</td><td><code>&quot;&quot;</code></td><td>Hover tooltip content.</td></tr><tr><td><code>frame</code></td><td>STRING</td><td>No</td><td><code>task</code></td><td>Which default sentence to use: <code>task</code>, <code>goal</code>, or <code>challenge</code>.</td></tr><tr><td><code>format</code></td><td>STRING</td><td>No</td><td><code>&quot;&quot;</code></td><td>Replaces the default sentence entirely when non-empty; supports <code>%player%</code> and <code>%title%</code>.</td></tr><tr><td><code>permission</code></td><td>STRING</td><td>No</td><td><code>&quot;&quot;</code></td><td>When non-empty, only players holding this permission receive the announcement.</td></tr><tr><td><code>console</code></td><td>BOOLEAN</td><td>No</td><td><code>true</code></td><td>Whether to echo the announcement to the console.</td></tr></tbody></table><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | codex_broadcast_achievement title=&quot;&lt;gold&gt;First Hunt&lt;/gold&gt;&quot; frame=task&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;player_by_name name=Steve | codex_broadcast_achievement title=&quot;&lt;light_purple&gt;Flawless Run&lt;/light_purple&gt;&quot; frame=challenge description=&quot;&lt;gray&gt;Cleared without taking damage&lt;/gray&gt;&quot;&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | codex_broadcast_achievement title=&quot;&lt;yellow&gt;Realm Opened&lt;/yellow&gt;&quot; format=&quot;&lt;white&gt;%player% lit up &lt;yellow&gt;[%title%]&lt;/yellow&gt;&lt;/white&gt;&quot; permission=emakicodex.use console=false&#39;</span></span></code></pre></div><p>Behavior:</p><ul><li>The stage executes on the global target but still requires a player in context: <code>%player%</code> comes from that target.</li><li>A blank <code>title</code> fails with <code>INVALID_CONFIG</code>, and a <code>frame</code> outside the three allowed values also fails with <code>INVALID_CONFIG</code>.</li><li>The default sentence comes from the language key <code>broadcast.frame.&lt;frame&gt;</code>, falling back to a built-in sentence when the key is missing.</li><li>On success it reports <code>player</code>, <code>title</code>, <code>frame</code>, and the <code>recipients</code> count that actually received the announcement.</li></ul><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to “Notes”">​</a></h2><ul><li>These stages only handle online players.</li><li>Node visibility, parent/child relationships, toasts, broadcasts, and completion actions are still controlled by <code>advancements/*.yml</code>.</li><li><code>codex_resync_advancement</code> and <code>codex_show_toast</code> require PacketEvents; the grant, revoke, reset, and broadcast stages do not.</li><li>When the relevant service is not ready, the stage fails with <code>MISSING_CONTEXT</code> rather than skipping silently.</li><li>To change category-entry state, use <code>/codex admin unlock</code>, <code>/codex admin reset</code>, or GUI interaction rather than these advancement stages.</li></ul>`,48)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};